81	    public func cancelAll() {
82	        pipelineTask?.cancel()
83	        cleanupTask?.cancel()
84	        pipelineGeneration &+= 1
85	        cleanupGeneration &+= 1
86	        activeRecordingId = nil
87	        // #73 G4: was a direct notifyStateChange(...) call, which skips
88	        // onCleanupStateChanged/onPipelineStateChanged (MenuBarViewModel's source)
89	        // and currentCleanupState/currentPipelineState. The generation bump above
90	        // also defeats the cancelled task's own clearStateIfActive, so these
91	        // setters are the only unconditional path to .idle.
92	        setCleanupState(.idle)
93	        setPipelineStateInternal(.idle)
94	    }
