96	    public func recoverPendingSession(_ recordingId: RecordingID) async {
97	        guard archivePassEnabled else { return }
98	        // The coordinator has single-slot state (one activeRecordingId/pipelineTask
99	        // at a time) — recovery must never cancel or clobber a session that's
100	        // already actively piping. Skip this recovery attempt entirely and let
101	        // it retry on a later launch.
102	        guard activeRecordingId == nil else {
103	            logger
104	                .info(
105	                    // swiftlint:disable:next line_length
106	                    "Skipping recovery for \(recordingId, privacy: .private) — a live session is already active",
107	                )
108	            return
109	        }
110	        logger.info("Recovering pending session: \(recordingId, privacy: .private)")
111	        // Set activeRecordingId synchronously before the cleanup pass, mirroring
112	        // startCleanupPass/startPipeline — otherwise performCleanupTranscription's
113	        // isActiveRecording guard (#73 G4 generation-race protection) always fails
114	        // for recovery, silently discarding an already-persisted cleaned transcript.
115	        activeRecordingId = recordingId
116	        guard let result = await performCleanupTranscription(recordingId: recordingId) else {
117	            // swiftlint:disable:next line_length
118	            logger.error("Recovery cleanup transcription did not complete — session stays pending: \(recordingId, privacy: .private)")
119	            return
120	        }
121	        startPipeline(for: recordingId, liveTranscription: result)
122	    }
