124	    /// #130: single post-stop entry point. The pass ordering (archive cleanup
125	    /// alongside the diarize→summarize pipeline) is Business knowledge —
126	    /// Presentation calls this and never sequences the passes itself.
127	    public func recordingCompleted(for recordingId: RecordingID, liveTranscription: TranscriptionResult) {
128	        startCleanupPass(for: recordingId)
129	        startPipeline(for: recordingId, liveTranscription: liveTranscription)
