132	    public func startPipeline(for recordingId: RecordingID, liveTranscription: TranscriptionResult) {
133	        pipelineTask?.cancel()
134	        activeRecordingId = recordingId
135	        pipelineGeneration &+= 1
136	
137	        let generation = pipelineGeneration
138	
139	        pipelineTask = Task {
140	            // #73 G5: clear our Task ref on every exit, unless a newer generation
141	            // already superseded us (then it isn't ours to clear).
142	            defer { if pipelineGeneration == generation { pipelineTask = nil } }
143	
144	            await runPipelinePasses(
145	                recordingId: recordingId,
146	                liveTranscription: liveTranscription,
147	                generation: generation,
148	            )
149	
150	            // #132: the pipeline is done with the ML engines — success or
151	            // failure — so on memory-constrained machines release model memory
152	            // (same policy as the ASR unload in startCleanupPass). Skipped when
153	            // a newer generation superseded us: that pipeline needs the engines.
154	            guard !Task.isCancelled, pipelineGeneration == generation else { return }
155	            await unloadPipelineEnginesIfConstrained()
156	        }
157	    }
