159	    private func runPipelinePasses(
160	        recordingId: RecordingID,
161	        liveTranscription: TranscriptionResult,
162	        generation: Int,
163	    ) async {
164	        logger.info("Pipeline START for \(recordingId, privacy: .public)")
165	        setPipelineState(.diarizing, generation: generation)
166	
167	        guard let diarizationResult = await runDiarizationPass(
168	            recordingId: recordingId,
169	            transcription: liveTranscription,
170	            generation: generation,
171	        ) else {
172	            return
173	        }
174	
175	        guard !Task.isCancelled else { return }
176	
177	        await runSummarizationPass(recordingId: recordingId, transcript: diarizationResult, generation: generation)
178	    }
