180	    private func unloadPipelineEnginesIfConstrained() async {
181	        guard physicalMemory < PipelineCoordinator.memoryUnloadThreshold else { return }
182	        await diarizationEngine?.unloadModel()
183	        await summarizationEngine?.unloadModel()
184	    }
