186	    public func startCleanupPass(for recordingId: RecordingID) {
187	        guard archivePassEnabled else { return }
188	
189	        cleanupTask?.cancel()
190	        activeRecordingId = recordingId
191	        cleanupGeneration &+= 1
192	        let generation = cleanupGeneration
193	
194	        let engine = primaryEngine
195	        let shouldUnload = physicalMemory < PipelineCoordinator.memoryUnloadThreshold
196	
197	        cleanupTask = Task {
198	            // #73 G5: same generation-guarded clear as pipelineTask above.
199	            defer { if cleanupGeneration == generation { cleanupTask = nil } }
200	
201	            setCleanupState(.running)
202	            if shouldUnload, let engine {
203	                await engine.unloadModel()
204	            }
205	            let result = await performCleanupTranscription(recordingId: recordingId)
206	            if let result {
207	                setCleanupState(.complete(result))
208	            } else {
209	                setCleanupState(.idle)
210	            }
211	        }
212	    }
