214	    public func runCleanupPass(recordingId: RecordingID) async -> TranscriptionResult? {
215	        setCleanupState(.running)
216	        let result = await performCleanupTranscription(recordingId: recordingId)
217	        if let result {
218	            setCleanupState(.complete(result))
219	            setPipelineStateInternal(.diarizing)
220	        } else {
221	            setCleanupState(.idle)
222	        }
223	        return result
224	    }
