226	    private func performCleanupTranscription(recordingId: RecordingID) async -> TranscriptionResult? {
227	        do {
228	            let result = try await cleanupTranscribe.transcribeCleanupPass(
229	                recordingId: recordingId,
230	                modelId: ModelIDs.cleanupTranscription,
231	            )
232	            guard !Task.isCancelled else { return nil }
233	            guard isActiveRecording(recordingId) else { return nil }
234	            return result
235	        } catch {
236	            if error is CancellationError { return nil }
237	            let msg = "Cleanup transcription failed: \(error.userFacingMessage)"
238	            logger.error("\(msg, privacy: .private)")
239	            onPipelineError?(msg)
240	            return nil
241	        }
242	    }
