244	    private func runDiarizationPass(
245	        recordingId: RecordingID,
246	        transcription: TranscriptionResult,
247	        generation: Int,
248	    ) async -> DiarizedTranscript? {
249	        do {
250	            let result = try await diarizeMeeting.diarize(recordingId: recordingId, transcription: transcription)
251	            guard !Task.isCancelled else {
252	                clearStateIfActive(generation: generation)
253	                return nil
254	            }
255	            guard isActiveRecording(recordingId) else {
256	                clearStateIfActive(generation: generation)
257	                return nil
258	            }
259	
260	            setPipelineState(.summarizing(result), generation: generation)
261	            return result
262	        } catch {
263	            // #73 G4: cancellation thrown from diarizeMeeting.diarize() itself, not
264	            // just noticed after it returns — same clearing as the guard above.
265	            if error is CancellationError {
266	                clearStateIfActive(generation: generation)
267	                return nil
268	            }
269	            let msg = "Diarization failed: \(error.userFacingMessage)"
270	            logger.error("\(msg, privacy: .private)")
271	            onPipelineError?(msg)
272	            setPipelineState(.failed(msg), generation: generation)
273	            return nil
274	        }
275	    }
