281	    private func runSummarizationPass(recordingId: RecordingID, transcript: DiarizedTranscript, generation: Int) async {
282	        do {
283	            let result = try await summarizeMeeting.summarize(recordingId: recordingId, transcript: transcript)
284	            guard !Task.isCancelled else {
285	                clearStateIfActive(generation: generation)
286	                return
287	            }
288	            guard isActiveRecording(recordingId) else {
289	                clearStateIfActive(generation: generation)
290	                return
291	            }
292	            setPipelineState(.complete(transcript, result), generation: generation)
293	        } catch {
294	            // #73 G4: cancellation thrown from summarize() itself — #144/T073-A only
295	            // patched the guard path above; this catch path left state stuck.
296	            if error is CancellationError {
297	                clearStateIfActive(generation: generation)
298	                return
299	            }
300	            let msg = "Summarization failed: \(error.userFacingMessage)"
301	            logger.error("\(msg, privacy: .private)")
302	            onPipelineError?(msg)
303	            setPipelineState(.failed(msg), generation: generation)
304	        }
305	    }
